def countSequences(nums, k):
    # Factor k into 2^a * 3^b * 5^c
    a = b = c = 0
    while k % 2 == 0:
        k //= 2
        a += 1
    while k % 3 == 0:
        k //= 3
        b += 1
    while k % 5 == 0:
        k //= 5
        c += 1
    # Any other prime factor can never be produced
    if k != 1:
        return 0

    # Exponent vector (of 2, 3, 5) for every allowed value 1..6
    exps = {
        1: (0, 0, 0),
        2: (1, 0, 0),
        3: (0, 1, 0),
        4: (2, 0, 0),
        5: (0, 0, 1),
        6: (1, 1, 0),
    }

    # dp maps current exponent triple -> number of ways to reach it
    dp = {(0, 0, 0): 1}
    for x in nums:
        ea, eb, ec = exps[x]
        new_dp = {}
        for (p, q, r), ways in dp.items():
            # sgn = -1 divide, 0 leave unchanged, +1 multiply
            for sgn in (-1, 0, 1):
                key = (p + sgn * ea, q + sgn * eb, r + sgn * ec)
                new_dp[key] = new_dp.get(key, 0) + ways
        dp = new_dp

    # Number of sequences ending exactly at the exponents of k
    return dp.get((a, b, c), 0)
